for(const f of [...new Set(eyes.map(e=>e.family))].sort()){let o=document.createElement('option');o.value=f;o.textContent=f;$('family').appendChild(o)}
function filter(){let q=$('query').value.toLowerCase(),f=$('family').value,s=$('status').value;let list=eyes.filter(e=>(!f||e.family===f)&&(!s||e.status===s)&&JSON.stringify(e).toLowerCase().includes(q));$('count').textContent=`${list.length} of ${eyes.length} eye versions`; $('cards').innerHTML=list.map(e=>`<article class="card"><div class="tag">${esc(e.status)} · ${esc(e.family)}</div><h3>${esc(e.title)}</h3><code>${esc(e.id)}@${esc(e.version)}</code><p>${esc(e.output_meaning)}</p><details><summary>Contract and limits</summary><pre class="contract">${esc(JSON.stringify(e,null,2))}</pre></details></article>`).join('')}
['query','family','status'].forEach(x=>$(x).addEventListener('input',filter));filter();document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('main>section').forEach(s=>s.hidden=s.id!==b.dataset.tab);document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));draw()});
function calculate(g,T){let pc=1/(1+Math.exp(1/.5)),ph=1/(1+Math.exp(g/T)),w=(g-1)*(ph-pc),qh=g*(ph-pc);return {pc,ph,w,qh,eta:w>0?w/qh:null}}
function draw(){let g=+$('gap').value,T=+$('temp').value,k=+$('stage').value/100;let a=calculate(g,T),paths=[[1,a.pc],[g,a.pc],[g,a.ph],[1,a.ph],[1,a.pc]],s=Math.min(3,Math.floor(k)),u=k===4?1:k-s,A=paths[s],B=paths[s+1],point=[A[0]+u*(B[0]-A[0]),A[1]+u*(B[1]-A[1])];$('gapv').textContent=g.toFixed(1);$('tempv').textContent=T.toFixed(1);$('stageName').textContent=['Compression · work on system','Heating · heat into system','Expansion · work out of system','Cooling · heat to bath'][s];let c=$('cycle'),x=c.getContext('2d'),W=c.width,H=c.height;x.clearRect(0,0,W,H);let X=v=>65+(v-1)/3*(W-110),Y=v=>H-50-v/.6*(H-90);x.strokeStyle='#42607e';x.lineWidth=1;x.beginPath();x.moveTo(65,30);x.lineTo(65,H-50);x.lineTo(W-40,H-50);x.stroke();x.fillStyle='#b5c8dd';x.font='14px system-ui';x.fillText('Excited population',15,20);x.fillText('Level spacing',W/2,H-12);for(let i=0;i<4;i++){x.strokeStyle=['#edc775','#ed766d','#69d7c4','#7cbaff'][i];x.lineWidth=3;x.beginPath();x.moveTo(X(paths[i][0]),Y(paths[i][1]));x.lineTo(X(paths[i+1][0]),Y(paths[i+1][1]));x.stroke()}x.fillStyle='#fff';x.beginPath();x.arc(X(point[0]),Y(point[1]),7,0,7);x.fill();$('ledger').textContent=`Work output per cycle: ${a.w.toFixed(4)}. Heat into hot stroke: ${a.qh.toFixed(4)}. ${a.eta===null?'This setting is not in the positive-work engine regime.':'Ideal efficiency: '+(100*a.eta).toFixed(1)+'%.'} Cycle closes at the final stage.`}
let timer=null;$('play').onclick=()=>{if(timer){clearInterval(timer);timer=null;$('play').textContent='Play cycle'}else{timer=setInterval(()=>{$('stage').value=(+$('stage').value+2)%401;draw()},40);$('play').textContent='Pause'}};$('reset').onclick=()=>{$('stage').value=0;draw()};['gap','temp','stage'].forEach(id=>$(id).oninput=draw);draw();$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('prompt').textContent);$('copy').textContent='Copied'}catch(e){$('copy').textContent='Select and copy the paragraph above'}};
